head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "uldmgt50309";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "if_lawTitle", fn: function(){ return (!(String(((dma_disclosureLawDetail.get("lawTitle") ?? (() => { throw new Error("unresolved:" + "disclosureLawDetail.lawTitle"); })())) == null ? '' : ((dma_disclosureLawDetail.get("lawTitle") ?? (() => { throw new Error("unresolved:" + "disclosureLawDetail.lawTitle"); })()))).length === 0)); } }, { id: "th_16", fn: function(){ return (!(String(((dma_disclosureLawDetail.get("lawTitle") ?? (() => { throw new Error("unresolved:" + "disclosureLawDetail.lawTitle"); })())) == null ? '' : ((dma_disclosureLawDetail.get("lawTitle") ?? (() => { throw new Error("unresolved:" + "disclosureLawDetail.lawTitle"); })()))).length === 0)); } }, { id: "if_lawTitle_3", fn: function(){ return (!(String(((dma_disclosureLawDetail.get("lawTitle") ?? (() => { throw new Error("unresolved:" + "disclosureLawDetail.lawTitle"); })())) == null ? '' : ((dma_disclosureLawDetail.get("lawTitle") ?? (() => { throw new Error("unresolved:" + "disclosureLawDetail.lawTitle"); })()))).length === 0)); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_pageBody = async function () {
    try {
        await scwin.findMainLaw();
        await scwin.findDetailLaw();

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'uldmgt50309.onpageload' }); }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

scwin.form_listForm = { action: "", method: 'post', target: '' };

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_conds();
        await scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'uldmgt50309.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name img_25_onclick
 * @description img_25 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.img_25_onclick = function(e){
    try {
        scwin.close()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'uldmgt50309.img_25_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_findMainLaw_xhr
 * @description find Main Law xhr 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_findMainLaw_xhr = async function () {
    // ⛔주소가 없다 — as-is 는 «자기 자신» 에게 제출했는데(`self_submit`) 화면 자신의 액션 URL 을
    //   하나로 못 정했다(후보 0 또는 여럿). 빈 주소로 내보내면 «조용히 엉뚱한 곳» 이다.
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — tx_findMainLaw_xhr"
    throw { bizMessage: "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — tx_findMainLaw_xhr", unresolved: "action:self_submit:tx_findMainLaw_xhr" };
};

/**
 * @method
 * @name tx_findDetailLaw_xhr
 * @description find Detail Law xhr 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_findDetailLaw_xhr = async function () {
    // ⛔주소가 없다 — as-is 는 «자기 자신» 에게 제출했는데(`self_submit`) 화면 자신의 액션 URL 을
    //   하나로 못 정했다(후보 0 또는 여럿). 빈 주소로 내보내면 «조용히 엉뚱한 곳» 이다.
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — tx_findDetailLaw_xhr"
    throw { bizMessage: "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — tx_findDetailLaw_xhr", unresolved: "action:self_submit:tx_findDetailLaw_xhr" };
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name findMainLaw
 * @description find Main Law 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.findMainLaw = async function () {
    scwin.form_listForm.action = "/filing/onlineDisclosureLaw.do";
    $c.util.getComponent('dma_findMainLawXhrReq').set('method', "findDisclosureLawStepItems");
    $c.util.getComponent('txt_mainLawDiv').setValue(await scwin.tx_findMainLaw_xhr());
};

/**
 * @method
 * @name findDetailLaw
 * @description find Detail Law 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.findDetailLaw = async function () {
    scwin.form_listForm.action = "/filing/onlineDisclosureLaw.do";
    $c.util.getComponent('dma_findMainLawXhrReq').set('method', "findDisclosureLawDetailedRuleStepItems");
    $c.util.getComponent('txt_detailLawDiv').setValue(await scwin.tx_findDetailLaw_xhr());
};

/**
 * @method
 * @name close
 * @description close 처리
 * @returns {void}
 * @hidden N
 */
scwin.close = function () {
    $c.win.closePopup();
};
